def sort_even(l: list):
    even_indices = sorted(l[i] for i in range(len(l)) if i % 2 == 0)
    result = l[:]  # Create a copy of the original list

    j = 0  # Pointer for the sorted even indices
    for i in range(len(l)):
        if i % 2 == 0:
            result[i] = even_indices[j]
            j += 1

    return result

